Use ASP.NET Core's `WebApplicationFactory<T>` to host your server in-process and test MCP over HTTP without binding to a real port:

```csharp
// MyMcpTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using Xunit;

public class McpTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2025-03-26",
            body.GetProperty("result")
                .GetProperty("protocolVersion")
                .GetString());
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/list",
            @params = new { }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

**Key points:**

1. **`WebApplicationFactory<Program>`** boots your full middleware pipeline in-memory — no TCP port needed.
2. **`CreateClient()`** gives you an `HttpClient` that talks directly to the in-memory test server.
3. If you need to override services (e.g., mock a database), use `.WithWebHostBuilder(b => b.ConfigureServices(...))`.
4. For **Streamable HTTP** (SSE-based sessions), use `HttpCompletionOption.ResponseHeadersRead` and read the stream:

```csharp
var response = await _client.SendAsync(request,
    HttpCompletionOption.ResponseHeadersRead);
using var stream = await response.Content.ReadAsStreamAsync();
using var reader = new StreamReader(stream);
// read SSE events line by line
```

5. Make sure `Program` is accessible — add `public partial class Program { }` at the bottom of your `Program.cs` if using top-level statements.

This gives you full protocol-level coverage (JSON-RPC framing, headers, session management) with the speed of an in-process call.
